// DC Motor Speed Control
// A potentiometer sets motor speed continuously from 0 to full, forward only.

const int POT_PIN = A0;
const int IN1 = 7;
const int IN2 = 8;
const int ENA = 9; // PWM

void setup() {
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(ENA, OUTPUT);

  // fixed forward direction for this project
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
}

void loop() {
  int potValue = analogRead(POT_PIN);      // 0-1023
  int speed = map(potValue, 0, 1023, 0, 255); // rescale to PWM's 0-255 range

  analogWrite(ENA, speed);
}
